import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Where uploaded photos live. Only a local-disk version exists for now; an
 * S3/MinIO version just needs to implement the same three methods and be
 * returned from photoStorage().
 */
export interface PhotoStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

// Keys are generated by us as <uuid>.webp. Anything else is refused, which
// also rules out path traversal.
export const PHOTO_KEY_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.webp$/;

class LocalDiskStorage implements PhotoStorage {
  constructor(private readonly dir: string) {}

  private file(key: string): string {
    if (!PHOTO_KEY_PATTERN.test(key)) throw new Error("Invalid photo key");
    return path.join(this.dir, key);
  }

  async put(key: string, data: Buffer): Promise<void> {
    await mkdir(this.dir, { recursive: true });
    await writeFile(this.file(key), data);
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.file(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw err;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.file(key), { force: true });
  }
}

let storage: PhotoStorage | undefined;

export function photoStorage(): PhotoStorage {
  storage ??= new LocalDiskStorage(process.env.UPLOAD_DIR || path.join(process.cwd(), "data", "uploads"));
  return storage;
}
